	[6001] = {
		id = 6001,
		name = 'Martial Arts Tournament Gold Chest',
		name_vn = 'Đại Hội Võ Thuật Rương Vàng',
		name_en = 'Martial Arts Tournament Gold Chest',
		name_th = 'หีบทองศึกศิลปะการต่อสู้',
		name_in = 'Peti Emas Turnamen Seni Bela Diri',
		name_ph = 'Gintong Kabaong ng Paligsahan ng Martial Arts',
		name_ma = 'Petik Emas Kejohanan Seni Mempertahankan Diri',
		icon = 'config/item/icon_box_vs2.png',
		desc = 'Reward chest for winners of the Martial Arts Tournament, may contain gold, Martial Arts Gold Medal, affection gift, talent training material, awakening item, jewelry star-up material, and other resources.',
		desc_vn = 'Rương phần thưởng cho người chiến thắng trong Đại Hội Võ Đạo, khi mở có cơ hội nhận được vàng, Huy Chương Vàng Võ Đạo, vật phẩm tăng độ hảo cảm, nguyên liệu bồi dưỡng thiên phú, vật phẩm thức tỉnh và tăng sao trang sức cùng các phần thưởng tài nguyên khác.',
		desc_en = 'Reward chest for winners of the Martial Arts Tournament, may contain gold, Martial Arts Gold Medal, affection gift, talent training material, awakening item, jewelry star-up material, and other resources.',
		desc_th = 'หีบรางวัลผู้ชนะในงาน Martial Arts มีโอกาสได้รับทอง, เหรียญทอง Martial Arts, ของขวัญเพิ่มความสัมพันธ์, วัสดุฝึกฝนพรสวรรค์, ไอเท็มปลุกพลัง, วัสดุอัปดาวเครื่องประดับ และรางวัลอื่น ๆ',
		desc_in = 'Peti hadiah untuk pemenang Turnamen Bela Diri, bisa mendapatkan emas, Medali Emas Bela Diri, hadiah keintiman, bahan pelatihan bakat, item kebangkitan, bahan peningkatan bintang perhiasan, dan hadiah sumber daya lainnya.',
		desc_ph = 'Kahon ng gantimpala para sa mga nanalo sa Martial Arts Tournament, may tsansang makakuha ng ginto, Martial Arts Gold Medal, regalo ng pagkakaibigan, materyal sa pagsasanay ng talento, item sa paggising, materyal sa pagpapataas ng bituin ng alahas, at iba pang gantimpala.',
		desc_ma = 'Petis hadiah untuk pemenang Pertandingan Seni Bela Diri, mungkin mengandungi emas, Pingat Emas Seni Bela Diri, hadiah hubungan, bahan latihan bakat, item kebangkitan, bahan naik taraf bintang barang kemas dan ganjaran sumber lain.',
		quality = 5,
		type = 7,
		specialArgsMap = __data_t__specialArgsMap[6001],
